# assets/icons/icons.map -- THE ONE PLACE where an icon name meets a
# code point.  Everything else in this round is generated from this file:
# the icon font (`assets/osum-icons.ttf`), the constants the code uses
# (`lib/icons.fi`) and the list the tests walk.
#
# WHY A FILE AND NOT A TABLE IN THE SOURCE.  A code point in a private
# use area is a number with no meaning outside this system.  Written into
# a drawing routine it is unsearchable: nobody reading `0xE041` two years
# from now can find out what it is, and nobody can tell whether a second
# routine picked the same number for something else.  Here the number
# appears exactly once, next to a name and next to the glyph it was cut
# from, and `tools/icons/rawcp.py` fails the build if a raw code point
# turns up in drawing code.
#
# THE LAYOUT, and the reason it has gaps: code points are an interface.
# Once a name has a number, the number does not move -- a disk image
# built last week must keep working with a kernel built today.  New
# icons go into the gap at the end of their block; they never push an
# existing one along.
#
#   E000..E01F  network
#   E020..E03F  power and battery
#   E040..E05F  window controls
#   E060..E07F  arrows, chevrons, navigation
#   E080..E09F  files and storage
#   E0A0..E0BF  general and status
#
# LINE FORMAT
#
#   <name> = <code point, hex> <source glyph name>
#   <name> = alias <other name>
#
# An ALIAS is a second name for the same code point.  Explorer's "back"
# button and a plain left arrow ARE the same shape -- Windows draws them
# the same way too -- and cutting the same outline into the font twice
# would be dishonest about the size.  The alias exists so the call site
# can say what it MEANS (`icon.nav.back`) instead of what it looks like.
#
# SOURCE: Lucide 0.469.0, ISC licence, see LICENSE.lucide in this
# directory and docs/ICONS.md for why this font and not another.

# ------------------------------------------------------------ network
#
# THERE IS NO WIRELESS ICON IN THIS LIST, and that is a decision, not an
# oversight.  This system has no 802.11 driver -- `kernel/inet.fi` knows
# virtio-net and nothing else.  An icon for a radio that does not exist
# would be the interface lying to the person in front of it.
icon.network.wired          = E000 cable
icon.network.offline        = E001 unplug
icon.network.no-internet    = E002 cloud-off
# The three views of round NETVIEW.  Each one has to be told apart by
# SHAPE, because a person who cannot separate red from green still has
# to see which of them is on: a mask, a crossed circle and a funnel are
# three different outlines before they are three different colours.
icon.network.faked          = E003 venetian-mask
icon.network.blocked        = E004 ban
icon.network.filtered       = E005 filter

# -------------------------------------------------- power and battery
#
# Four steps, not a percentage.  A battery drawn as a case with a number
# of bars can be read at sixteen pixels; a number cannot.
icon.battery.full           = E020 battery-full
icon.battery.medium         = E021 battery-medium
icon.battery.low            = E022 battery-low
icon.battery.empty          = E023 battery
icon.battery.charging       = E024 battery-charging
icon.battery.absent         = E025 battery-warning

# ---------------------------------------------------- window controls
#
# The four buttons a window frame has.  `restore` is two overlapping
# squares, which is what Windows and every other desktop uses; it is the
# only one of the four whose meaning is not plain from the shape alone,
# and that is exactly why it has a tooltip.
icon.window.close           = E040 x
icon.window.minimise        = E041 minus
icon.window.maximise        = E042 square
icon.window.restore         = E043 copy

# ------------------------------- arrows, chevrons and the navigation
icon.arrow.left             = E060 arrow-left
icon.arrow.right            = E061 arrow-right
icon.arrow.up               = E062 arrow-up
icon.arrow.down             = E063 arrow-down
icon.chevron.left           = E064 chevron-left
icon.chevron.right          = E065 chevron-right
icon.chevron.up             = E066 chevron-up
icon.chevron.down           = E067 chevron-down
icon.nav.refresh            = E068 rotate-cw
icon.nav.back               = alias icon.arrow.left
icon.nav.forward            = alias icon.arrow.right
icon.nav.up                 = alias icon.arrow.up

# ------------------------------------------------- files and storage
icon.file.folder            = E080 folder
icon.file.folder-open       = E081 folder-open
icon.file.file              = E082 file
icon.file.text              = E083 file-text
icon.file.image             = E084 image
icon.file.program           = E085 terminal
icon.file.drive             = E086 hard-drive

# -------------------------------------------------- general and status
#
# The four status icons are where the accessibility rule bites hardest:
# a triangle, a crossed circle, a ticked circle and a circled `i` differ
# in OUTLINE.  Take the colour out of all four -- which is what
# `tools/icons/sheet.py` does for the grey sheet -- and they are still
# four different things.
icon.settings               = E0A0 settings
icon.search                 = E0A1 search
icon.start                  = E0A2 layout-grid
icon.trash                  = E0A3 trash-2
icon.warning                = E0A4 triangle-alert
icon.error                  = E0A5 circle-x
icon.success                = E0A6 circle-check
icon.info                   = E0A7 info
icon.check                  = E0A8 check
icon.menu                   = E0A9 menu
